const j=$input.first().json;
if(!Array.isArray(j.posts)||!j.posts.length) throw new Error('posts required');
const quota=Number(j.daily_posts); if(!Number.isInteger(quota)||quota<1||quota>20) throw new Error('daily_posts must be 1..20');
if(j.posts.length>quota) throw new Error('posts exceed source cadence setting');
return j.posts.map((p,i)=>{if(!p.character_id||!p.content_brief)throw new Error('each post needs character_id/content_brief');return {json:{character_id:p.character_id,content_brief:p.content_brief,day_slot:i+1,source_tools:['Claude','Higgsfield','GoHighLevel (identity/contracts unresolved)'],status:'manual_generation_and_schedule_handoff',publish:'not_enabled'}}});
